import { Animation } from '@wix/wix-ui-icons-common/lazy';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { getIsModalOpen, useModalState } from './../../ricos-modals/modal-service-provider.js';
import type { IToolbarItem, Resolver, RicosServices, ToolbarButton } from './../../ricos-types/index.js';
import type { Node as ProseMirrorNode } from './../../tiptap/pm/model.js';
import { FLOATING_PLUGIN_TOOLBAR } from './../../toolbars-v3/index.js';

import { PLUGIN_TOOLBAR_ANIMATION_BUTTON } from '../data-hooks.js';
import { PmNodeType } from '../pm-node-types.js';
import { getNodeInSelection } from '../resolvers/get-node-in-selection.js';
import { ToolbarButton as ToolbarButtonComponent } from '../toolbar-button/toolbar-button.js';
import { PLUGIN_TOOLBAR_BUTTON_ID } from './plugin-toolbar-buttons-ids.js';

export const ANIMATION_PANEL_ID = 'animation-panel';

/**
 * image/video/gif selections may sit on the FIGURE wrapper — the data node, which
 * is the one carrying `animation`, is its child. `firstChild` is null for an empty
 * FIGURE, leaving nothing to animate.
 */
const getAnimationTargetNode = (node: ProseMirrorNode | undefined) =>
  node?.type?.name === PmNodeType.FIGURE ? node.firstChild : node;

/**
 * Shared animation button for node plugin toolbars. Visible only when the
 * opt-in `pluginAnimation` is registered — the panel component arrives through
 * `PluginExports`, so panel code ships only inside the plugin module, never in
 * editors that don't use the feature. Both `visible` and `command` resolve at
 * render/click time, so plugin registration order doesn't matter.
 *
 * Desktop only, matching the formatting toolbar — `FORMATTING_BUTTONS.ANIMATION`
 * is in `desktopTextButtonList` but not `mobileTextButtonList`.
 *
 * By default the target is the node in a NodeSelection; plugins with a custom
 * selection model (table cell selections) pass their own `selectedNode` resolver.
 */
export const createAnimationButton = (
  services: RicosServices,
  selectedNode: Resolver<ProseMirrorNode | undefined> = getNodeInSelection
): ToolbarButton => ({
  id: PLUGIN_TOOLBAR_BUTTON_ID.ANIMATION,
  type: 'modal',
  icon: Animation,
  tooltip: 'AnimationButton_Tooltip',
  dataHook: PLUGIN_TOOLBAR_ANIMATION_BUTTON,
  attributes: {
    selectedNode,
    // desktop only, and requires the opt-in plugin AND a resolvable target node
    visible: (content, resolverServices, editor) =>
      !services.context.isMobile &&
      Boolean(services.plugins.getExports().animation) &&
      Boolean(selectedNode(content, resolverServices, editor)),
    // the LINK button's contract: active whenever the target already carries the
    // attribute, panel-open state is ORed in by the renderer
    active: (content, resolverServices, editor) =>
      Boolean(
        getAnimationTargetNode(selectedNode(content, resolverServices, editor))?.attrs.animation
      ),
  },
  renderer: toolbarItem => <AnimationButton toolbarItem={toolbarItem} />,
  command: ({ referenceElement, attributes: { selectedNode } }) => {
    const Panel = services.plugins.getExports().animation?.Panel;
    if (!Panel || !selectedNode) {
      return;
    }
    const node = getAnimationTargetNode(selectedNode);
    if (!node) {
      return;
    }
    services.modals.togglePluginPanel({
      id: ANIMATION_PANEL_ID,
      Component: Panel,
      componentProps: {
        referenceElement,
        nodeId: node.attrs.id,
        nodeType: node.type.name,
      },
      positioning: {
        referenceElement:
          referenceElement?.closest(`[data-hook~=${FLOATING_PLUGIN_TOOLBAR}]`) ?? referenceElement,
        placement: 'right-start',
      },
      focusReturnElement: referenceElement,
      isMobile: services.context.isMobile,
    });
  },
});

const AnimationButton: React.FC<{ toolbarItem: IToolbarItem }> = ({ toolbarItem }) => {
  const [referenceElement, setReferenceElement] = useState<HTMLButtonElement | null>(null);
  const { isMobile, t } = useContext(RicosContext) || {};
  // read inline (LinkButton pattern) so the content-derived `active` stays current
  const isPanelOpen = useModalState(getIsModalOpen(ANIMATION_PANEL_ID));
  const onClick = toolbarItem.commands.click;

  return (
    <ToolbarButtonComponent
      prefix={Animation}
      active={isPanelOpen || Boolean(toolbarItem.attributes.active)}
      onClick={() => onClick({ isMobile, referenceElement })}
      dataHook={PLUGIN_TOOLBAR_ANIMATION_BUTTON}
      tooltip={t('AnimationButton_Tooltip')}
      ariaLabel={t('AnimationButton_Tooltip')}
      ref={setReferenceElement}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
