import type { FC } from 'react';
import React from 'react';

import { ToggleButton } from './../../ui-components/index.js';

import styles from './list-item-toggle-scss.js';

type Props = {
  dataHook: string;
  title: string;
  infoContent?: string;
  selected: boolean;
  disabled?: boolean;
  onChange: () => void;
};

export const ListItemToggle: FC<Props> = ({
  title,
  infoContent,
  dataHook,
  selected,
  onChange,
  disabled,
}) => {
  return (
    <div className={styles.container}>
      <ToggleButton
        title={title}
        checked={selected}
        onChange={onChange}
        infoContent={infoContent}
        dataHook={dataHook}
        size="small"
        disabled={disabled}
      />
    </div>
  );
};
